import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Tokens","description":"","frontmatter":{},"headers":[],"relativePath":"tokens.md","filePath":"tokens.md"}'),n={name:"tokens.md"};function r(i,e,s,h,c,l){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h1><p>The tokens are the named values that components and pages use. They are CSS custom properties with the prefix <code>--kata-</code>, defined in <code>src/tokens/tokens.css</code> and written with the <a href="./scale">scale</a>. Only three kinds of value carry names of their own (spacing, type and color); the rest are plain properties such as a line width or a layer order, and the heights are named after the component they belong to.</p><p><code>@sakuzu/kata/tokens.css</code> contains the scale and the tokens without any global rule. <code>@sakuzu/kata</code> adds the base CSS described at the end.</p><h2 id="spacing" tabindex="-1">Spacing <a class="header-anchor" href="#spacing" aria-label="Permalink to &quot;Spacing&quot;">​</a></h2><p>Two scales, never mixed. The same step name means a different length in each, and each property uses only one of them: <code>padding</code> takes <code>pad-*</code>, <code>gap</code> and the margin of a page take <code>gap-*</code>.</p><table tabindex="0"><thead><tr><th>Token</th><th>Value</th><th>Measured against</th></tr></thead><tbody><tr><td><code>--kata-pad-&lt;step&gt;</code></td><td><code>--kata-size-&lt;step&gt;</code></td><td>the component&#39;s text (em)</td></tr><tr><td><code>--kata-gap-&lt;step&gt;</code></td><td><code>--kata-size-&lt;step&gt;-rem</code></td><td>the root (rem)</td></tr></tbody></table><p>The steps are 2xs, xs, sm, md, lg, xl and 2xl. Padding is in em so that a component with larger text gets proportionally more room. Gaps are in rem because a layout has no text of its own and must not multiply as it is nested.</p><table tabindex="0"><thead><tr><th>Step</th><th>pad (inside)</th><th>gap (between)</th></tr></thead><tbody><tr><td>2xs</td><td>an icon and its text</td><td>an icon and its text</td></tr><tr><td>xs</td><td>a badge, above and below</td><td>a label and its input</td></tr><tr><td>sm</td><td>a small button, above and below</td><td>items of one group</td></tr><tr><td>md</td><td>a button or list item, all sides</td><td>unrelated items</td></tr><tr><td>lg</td><td>the head of a page</td><td>sections of a screen</td></tr><tr><td>xl</td><td>(not used)</td><td>sections of a long page</td></tr></tbody></table><h2 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to &quot;Type&quot;">​</a></h2><p>Nine roles, each with a size, a line height (leading), a letter spacing (tracking) and, for the roles that head something, an offset: the distance to the text that follows.</p><table tabindex="0"><thead><tr><th>Role</th><th>Scale step</th><th>Leading</th><th>Weight</th><th>Use</th></tr></thead><tbody><tr><td>num</td><td>display2</td><td>half</td><td>600</td><td>measured values, amounts</td></tr><tr><td>title</td><td>title1</td><td>half</td><td>600</td><td>the title of a page</td></tr><tr><td>h1</td><td>title2</td><td>half</td><td>600</td><td>the title of a screen</td></tr><tr><td>h2</td><td>title3</td><td>half</td><td>600</td><td>the title of a section or card</td></tr><tr><td>prose</td><td>heading</td><td>whole</td><td>400</td><td>reading text</td></tr><tr><td>body</td><td>body</td><td>whole</td><td>400</td><td>interface text</td></tr><tr><td>caption</td><td>subheading</td><td>whole</td><td>400</td><td>notes, dates, hints</td></tr><tr><td>label</td><td>body</td><td>half</td><td>600</td><td>the name of a field or group</td></tr><tr><td>glyph</td><td>capline</td><td>half</td><td>600</td><td>characters inside a mark</td></tr></tbody></table><p>The tokens are <code>--kata-text-size-&lt;role&gt;</code>, <code>--kata-text-leading-&lt;role&gt;</code> and <code>--kata-text-tracking-&lt;role&gt;</code>, and <code>--kata-text-offset-&lt;role&gt;</code> for num, title, h1, h2, prose, caption and label. The weight is set by the component, not by a token.</p><ul><li>Reading text is one quarter step larger than interface text, because a page meant to be read does not need the density of a tool.</li><li>A label is as large as the value it names; only its weight sets it apart.</li><li>Body and caption take the running line height, because outside a control they wrap as paragraphs. Inside a control the text is trimmed and the line height has no effect.</li><li>On an element whose language is Chinese or Japanese, every tracking token is 0: CJK text takes no negative letter spacing.</li><li>Body and prose wrap pretty, so a paragraph does not end in one short word; the other roles wrap as they come (<code>text-wrap-style: auto</code>), as balancing narrows a Japanese caption and splits the words of a heading.</li></ul><h2 id="typeface-metrics" tabindex="-1">Typeface metrics <a class="header-anchor" href="#typeface-metrics" aria-label="Permalink to &quot;Typeface metrics&quot;">​</a></h2><p>The heights of controls are computed from the ink of their text, so the tokens carry the proportions of the typeface.</p><table tabindex="0"><thead><tr><th>Token</th><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--kata-cap</code></td><td>0.698</td><td>the cap height, as a ratio of the em</td></tr><tr><td><code>--kata-cjk-ascent</code></td><td>0.837</td><td>the top of CJK ink</td></tr><tr><td><code>--kata-cjk-descent</code></td><td>0.079</td><td>the bottom of CJK ink</td></tr><tr><td><code>--kata-ink-over</code></td><td>0</td><td>ink above the cap height</td></tr><tr><td><code>--kata-ink-under</code></td><td>0</td><td>ink below the baseline</td></tr><tr><td><code>--kata-ink</code></td><td>cap + over + under</td><td>the height of one line of ink</td></tr><tr><td><code>--kata-edge-top</code></td><td>over, in em</td><td>added back above a trimmed line</td></tr><tr><td><code>--kata-edge-bottom</code></td><td>under, in em</td><td>added back below a trimmed line</td></tr></tbody></table><p>When the root element&#39;s language is Chinese, Japanese or Korean, CJK ink reaches past the cap height and the baseline. <code>--kata-ink-over</code> becomes the ascent minus the cap height and <code>--kata-ink-under</code> the descent, so controls take their edges from the CJK ink.</p><h2 id="color" tabindex="-1">Color <a class="header-anchor" href="#color" aria-label="Permalink to &quot;Color&quot;">​</a></h2><p>The default theme is dark. <code>data-color-mode=&quot;light&quot;</code> on any element switches the elements inside it to the light values. All color tokens are <code>--kata-color-&lt;name&gt;</code>.</p><h3 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h3><p>From the lowest to the highest: <code>ground</code> (the page), <code>panel</code>, <code>raise</code> and <code>raise-2</code> (translucent, laid over the panel for hover and selection), <code>fill</code> (an opaque surface of the same weight as raise-2) and <code>solid</code> (the primary action), with <code>solid-hover</code>, <code>solid-active</code> and <code>on-solid</code> for the text on it. A disabled primary action takes <code>solid-disabled</code> with <code>solid-disabled-text</code> instead of being dimmed: the fill&#39;s grey with muted text in the dark theme, and a paler blue with white text in the light one.</p><h3 id="text-and-lines" tabindex="-1">Text and lines <a class="header-anchor" href="#text-and-lines" aria-label="Permalink to &quot;Text and lines&quot;">​</a></h3><p>Three levels of text: <code>text</code>, <code>muted</code> (close to text; secondary information) and <code>faint</code> (placeholders and disabled text only). Two levels of line: <code>line</code> and <code>line-strong</code>. Text reaches a contrast of 7:1 as a floor, not a target; lines and icons reach 3:1.</p><h3 id="hues" tabindex="-1">Hues <a class="header-anchor" href="#hues" aria-label="Permalink to &quot;Hues&quot;">​</a></h3><p>Four hues, each in three roles.</p><table tabindex="0"><thead><tr><th>Role</th><th>blue</th><th>yellow</th><th>red</th><th>green</th></tr></thead><tbody><tr><td>ink (text, lines)</td><td><code>blue-ink</code></td><td><code>yellow-ink</code></td><td><code>red-ink</code></td><td><code>green-ink</code></td></tr><tr><td>fill (a surface)</td><td><code>blue-fill</code></td><td><code>yellow-fill</code></td><td><code>red-fill</code></td><td><code>green-fill</code></td></tr><tr><td>on (text on fill)</td><td><code>on-blue</code></td><td><code>on-yellow</code></td><td><code>on-red</code></td><td><code>on-green</code></td></tr></tbody></table><p>An ink reaches 7:1 on the panel and on raise. The fills are the same in both themes; blue and red carry white text, yellow and green carry dark text, and blue and green differ in lightness as well as hue so that they stay apart for every kind of color vision. Red, the color of destructive actions, also has <code>red-fill-hover</code>, <code>red-fill-active</code> and <code>red-wash</code> (the hover surface of a destructive button). There are no pale tints. Meaning is never carried by color alone.</p><h3 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h3><p><code>focus</code> (the focus ring), <code>scrim</code> (the backdrop behind a modal) and <code>selection</code> (selected text).</p><h2 id="lines-and-corners" tabindex="-1">Lines and corners <a class="header-anchor" href="#lines-and-corners" aria-label="Permalink to &quot;Lines and corners&quot;">​</a></h2><p><code>--kata-border-width</code> is the one line width (1px). A focus ring, the selection mark of a list item and the underline of a tab are two lines wide. Corners are square; marks shaped as a capsule use <code>--kata-radius-pill</code>. There are no shadows.</p><h2 id="heights" tabindex="-1">Heights <a class="header-anchor" href="#heights" aria-label="Permalink to &quot;Heights&quot;">​</a></h2><p>Heights are named after the component they belong to, and each is a formula of the scale: the ink of the text, the padding and the lines.</p><table tabindex="0"><thead><tr><th>Token</th><th>Formula</th></tr></thead><tbody><tr><td><code>--kata-height-button</code></td><td>ink + md × 2 + line × 2</td></tr><tr><td><code>--kata-height-button-sm</code></td><td>ink + sm × 2 + line × 2</td></tr><tr><td><code>--kata-height-icon-button</code></td><td>= button-sm (a square)</td></tr><tr><td><code>--kata-height-list-item</code></td><td>ink + md × 2</td></tr><tr><td><code>--kata-height-list-item-two</code></td><td>list-item + gap-sm + caption ink</td></tr><tr><td><code>--kata-height-badge</code></td><td>caption ink + xs × 2 + line × 2</td></tr><tr><td><code>--kata-height-list-item-lg</code></td><td>button-sm + md × 2</td></tr><tr><td><code>--kata-height-list-item-mark</code></td><td>badge + md × 2</td></tr><tr><td><code>--kata-height-thumbnail-row</code></td><td>thumbnail + md × 2</td></tr><tr><td><code>--kata-height-toolbar</code></td><td>= list-item-lg</td></tr><tr><td><code>--kata-height-footer</code></td><td>button + md × 2</td></tr><tr><td><code>--kata-height-icon</code></td><td>1rem</td></tr><tr><td><code>--kata-height-thumbnail</code></td><td>2rem</td></tr></tbody></table><p>Here ink is <code>--kata-ink</code> times the component&#39;s text size, and md, sm and xs are the sizes of the scale times the same text size: body for every component except the badge, whose text is a caption.</p><h2 id="widths" tabindex="-1">Widths <a class="header-anchor" href="#widths" aria-label="Permalink to &quot;Widths&quot;">​</a></h2><p>Fixed widths of layout regions, in rem so that they grow with the root font size: <code>--kata-width-rail</code> (14.5rem), <code>-panel</code> (22.5rem), <code>-drawer</code> (17.5rem), <code>-modal-sm</code>, <code>-md</code>, <code>-lg</code> and <code>-xl</code> (25, 35, 45 and 60rem), <code>-popover</code> (18rem), <code>-toast</code> (22rem), <code>-prose</code> (46rem, the measure of reading text) and <code>-settings</code> (51.25rem).</p><h2 id="opacity-and-layers" tabindex="-1">Opacity and layers <a class="header-anchor" href="#opacity-and-layers" aria-label="Permalink to &quot;Opacity and layers&quot;">​</a></h2><p><code>--kata-opacity-dim</code> (0.64) dims disabled or busy content; disabled text still reaches 4.5:1. The layers, from the lowest, are <code>--kata-z-floating</code>, <code>-sheet</code>, <code>-menu</code>, <code>-modal</code> and <code>-toast</code>.</p><h2 id="fonts" tabindex="-1">Fonts <a class="header-anchor" href="#fonts" aria-label="Permalink to &quot;Fonts&quot;">​</a></h2><p><code>--kata-font-sans</code> is IBM Plex Sans, then IBM Plex Sans JP and Noto Sans SC and TC for CJK text, then the system font. kata does not load these fonts; an application that wants them loads them itself. <code>--kata-font-mono</code> names only the monospace faces of the systems (ui-monospace, SF Mono, Menlo, Consolas, Liberation Mono), so that it never falls back to Courier; an application that loads a monospace font of its own puts it first by setting <code>--kata-font-mono</code>.</p><h2 id="base-css" tabindex="-1">Base CSS <a class="header-anchor" href="#base-css" aria-label="Permalink to &quot;Base CSS&quot;">​</a></h2><p><code>src/base/base.css</code> holds the rules that apply to the whole page, and nothing a component looks like.</p><ul><li>Every box is <code>border-box</code>.</li><li><code>html</code> and <code>body</code> take the full height, and both are painted with <code>ground</code>. <code>body</code> sets the text color, the sans font and the body role.</li><li>The text size setting is <code>data-font-scale</code> on <code>html</code>: <code>large</code>, <code>larger</code>, <code>largest</code> and <code>max</code> set the root to 125%, 150%, 175% and 200%. Every length follows, through rem and em.</li><li><code>body</code> is the size container named <code>app</code>. Layouts query its width at three breakpoints: below 24rem, 48rem and 64rem. A <a href="./workbench/shell">Shell</a>&#39;s root is the <code>app</code> container of what is inside it, with or without the base CSS.</li><li>The margins of headings, paragraphs, lists and figures are removed, and lists lose their markers. Form controls lose the border, padding and font the browser gives them, so the only border on a control is the one its component draws.</li><li>Links are <code>blue-ink</code> and underlined on hover.</li><li>The focus ring shows for keyboard focus only, two lines wide in <code>focus</code>, outside the element.</li><li><code>[hidden]</code> always hides.</li></ul>',44)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
